(5, 1, 'A patient has a temperature of 39¬∞C. This is classified as:', NULL, 'A. Hypothermia', 'B. Normal', 'C. Fever', 'D. Hyperglycemia', NULL, 'C', 1.00, 5, 1, '2026-09-08 14:18:19'),
